CSS = ''':root{--ink:#17211d;--muted:#64706a;--paper:#fffdf7;--green:#176b4d;--green-soft:#e6f1eb;--line:#d9ded8;--bg:#edf1ed;--red:#9d3030;--amber:#936414}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 ui-sans-serif,system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:28px 20px 60px}h1,h2,h3,p{margin-top:0}.topbar{display:flex;align-items:center;gap:16px}.topbar h1{margin:0}.topbar .meta{margin-left:auto}.eyebrow{margin:0 0 4px;color:var(--green);font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.17em}.paper{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:26px;box-shadow:0 8px 30px #24352c12}.login-wrap{min-height:100vh;display:grid;place-items:center}.login-card{width:min(440px,100%)}.mark{display:grid;place-items:center;width:46px;height:46px;flex:0 0 46px;border-radius:12px;background:var(--green);color:white;font-size:20px;font-weight:800}.field,label{display:block;margin:12px 0;color:var(--muted)}input,textarea,select{display:block;width:100%;padding:10px;margin-top:5px;border:1px solid var(--line);border-radius:6px;background:white;color:var(--ink);font:inherit}textarea{resize:vertical}button{border:1px solid var(--green);background:var(--green);color:white;padding:9px 13px;border-radius:6px;cursor:pointer;font:inherit}button:disabled{opacity:.55;cursor:not-allowed}.ghost,nav button:not(.active){background:transparent;color:var(--green)}.danger{background:var(--red);border-color:var(--red)}nav{display:flex;gap:8px;margin:20px 0}.primary button{flex:1;text-align:left}.primary span{display:inline-grid;place-items:center;width:24px;height:24px;margin-right:6px;border-radius:50%;background:#ffffff44}.section-head,.dialog-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.card{border-bottom:1px solid var(--line);padding:17px 0}.card:last-child{border:0}.card-row{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.card button.open{background:transparent;color:var(--ink);border:0;padding:0;text-align:left}.meta,.empty,.notice{color:var(--muted)}.notice.error{color:var(--red)}.actions,.controls,.keyword-box{display:flex;align-items:flex-end;gap:8px;flex-wrap:wrap;margin-top:10px}.controls label{min-width:150px;margin:0}.keyword-box .field{flex:1;margin:0}.pill{display:inline-block;padding:3px 8px;border-radius:999px;background:var(--green-soft);color:var(--green);font-size:12px}.source{font-weight:800;color:var(--green)}.analytics-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:22px}.analytics-grid article{border:1px solid var(--line);border-radius:8px;padding:18px}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.metric{padding:12px;background:#f2f5f2;border-radius:7px}.metric strong{display:block;font-size:20px}.delta{font-size:12px;color:var(--green)}dl{display:grid;grid-template-columns:max-content 1fr;gap:8px 16px}dt{color:var(--muted)}dd{margin:0}dialog{width:min(920px,calc(100% - 32px));max-height:90vh;border:1px solid var(--line);border-radius:12px;padding:24px;background:var(--paper);color:var(--ink)}dialog::backdrop{background:#112019a8}.nested{border-bottom:1px solid var(--line)}.article-sheet{max-width:720px;margin:auto;padding:28px;background:white;border:1px solid var(--line);box-shadow:0 8px 24px #1f2b2510}.article-sheet.dark{background:#17211d;color:#eef4ef;border-color:#394b42}.article-sheet img{display:block;max-width:100%;height:auto;margin:18px auto}.article-sheet pre{white-space:pre-wrap;font:inherit}.image-slot{display:grid;place-items:center;min-height:180px;margin:18px 0;padding:20px;border:2px dashed var(--line);text-align:center;color:var(--muted)}.pipeline{border-left:4px solid var(--amber);padding:12px 16px;background:#fff8e8}.file-row,.trend-row,.watch-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}.subject-box{display:flex;align-items:flex-end;gap:8px;flex-wrap:wrap;margin-top:10px}.subject-box .field{flex:1;margin:0}.keywords{margin:6px 0}.keywords .pill{margin:0 4px 4px 0}.outline{margin:8px 0;max-width:70ch}.inline-form{margin-top:10px;padding:12px;background:#f2f5f2;border-radius:7px}.inline-form .field{margin:0}.history-row{padding:8px 0;border-top:1px solid var(--line)}details{margin:14px 0}summary{cursor:pointer;color:var(--green);font-weight:700}.source-missing{color:var(--red)}
/* Status is never colour alone — every pill carries its own word. */
.pill.status-proposed{background:var(--green-soft);color:var(--green)}.pill.status-revising{background:#fff3d6;color:var(--amber)}.pill.status-approved,.pill.status-carded{background:#dfeee5;color:var(--green)}.pill.status-rejected{background:#f7e4e4;color:var(--red)}@media print{body{background:white}body>*{display:none}dialog[open]{display:block;position:static;max-height:none;width:100%;border:0}.dialog-head,.nested,.reader-actions{display:none}.article-sheet{border:0;box-shadow:none;max-width:none}}@media(max-width:700px){main{padding:18px 12px}.paper{padding:16px}.topbar{flex-wrap:wrap}.topbar .meta{margin-left:62px}.primary{overflow:auto}.primary button{min-width:125px}.analytics-grid{grid-template-columns:1fr}.card-row,.section-head{display:block}dl{display:block}dt{margin-top:9px}.keyword-box{display:block}}'''

# Compatibility for existing page modules; new pages import CSS.
STYLE = CSS
